        }
      },
      derivedContext: {
        calendarLoad: 'low',
        isMondayOrTuesday: false,
        preferredPlanningWindow: {
          start: '17:00',
          end: '23:00'
        }
      }
    },
    recommendationEngineOutput:
      input.recommendationEngineOutput ||
      (
        input.result?.topRecommendations
          ? input
          : sampleRecommendationEngineOutput
      ),
