const input = $json || {};
const recommendationEngineOutput =
  input.recommendationEngineOutput || {};

const recommendations =
  recommendationEngineOutput.result?.topRecommendations ||
  recommendationEngineOutput.topRecommendations ||
  [];

const request = input.request || {};
const context = input.context || {};
const metadata = input.metadata || {};

const actions = [];
const logs = [];
const rejectedRecommendations = [];

const createActionId = (recommendationId, actionType, index) =>
  `${recommendationId || 'rec'}-${actionType}-${index + 1}-${Date.now()}`;

const requiresApprovalByType = actionType => [
  'calendar_create',
  'calendar_update',
  'calendar_delete',
  'send_external_message',
  'send_email',
  'reservation_prepare',
  'reservation_execute',
  'purchase_prepare',
  'purchase_execute',
  'share_personal_data'
].includes(actionType);

const riskByType = actionType => {
  if ([
    'purchase_execute',
    'reservation_execute',
    'calendar_delete',
    'share_personal_data'
  ].includes(actionType)) return 'high';

  if ([
    'calendar_create',
    'calendar_update',
    'send_external_message',
    'send_email',
    'reservation_prepare',
    'purchase_prepare'
  ].includes(actionType)) return 'medium';

  return 'low';
};

const addAction = ({
  recommendation,
  type,
  title,
  description,
  payload = {},
  channel = null,
  scheduledFor = null,
  priority = 'normal',
  autoExecutable = false
}) => {
  const action = {
    actionId: createActionId(
      recommendation.id,
      type,
      actions.length
    ),
    recommendationId: recommendation.id,
    recommendationTitle: recommendation.title,
    type,
    title,
    description,
    payload,
    channel,
    scheduledFor,
    priority,
    riskLevel: riskByType(type),
    approvalRequired: requiresApprovalByType(type),
    autoExecutable:
      autoExecutable && !requiresApprovalByType(type),
    status: 'planned',
    createdAt: new Date().toISOString()
  };

  actions.push(action);
};

for (const recommendation of recommendations) {
  if (!recommendation?.id || !recommendation?.title) {
    rejectedRecommendations.push({
      recommendation,
      reason: 'missing_id_or_title'
    });
    continue;
  }

  const category = String(
    recommendation.category || 'general'
  ).toLowerCase();

  addAction({
    recommendation,
    type: 'show_recommendation',
    title: `Show recommendation: ${recommendation.title}`,
    description:
      recommendation.reason ||
      'Present this recommendation to the user.',
    payload: {
      recommendation
    },
    channel: request.channel || 'chatgpt',
    priority:
      recommendation.rank === 1
        ? 'high'
        : 'normal',
    autoExecutable: true
  });

  if (recommendation.start && recommendation.end) {
    addAction({
      recommendation,
      type: 'calendar_create',
      title: `Add ${recommendation.title} to calendar`,
      description:
        'Prepare a Google Calendar event for user approval.',
      payload: {
        title: recommendation.title,
        start: recommendation.start,
        end: recommendation.end,
        location: recommendation.location || '',
        description:
          recommendation.reason || '',
        sourceUrl:
          recommendation.sourceUrl || null,
        reminders: [
          {
            method: 'popup',
            minutes: 60
          }
        ]
      },
      priority: recommendation.rank === 1 ? 'high' : 'normal'
    });

    addAction({
      recommendation,
      type: 'personal_reminder',
      title: `Reminder for ${recommendation.title}`,
      description:
        'Prepare a personal reminder before the activity.',
      payload: {
        recommendationId: recommendation.id,
        eventTitle: recommendation.title,
        eventStart: recommendation.start,
        reminderMinutesBefore: 60
      },
      channel: 'telegram',
      scheduledFor: recommendation.start,
      autoExecutable: true
    });
  }

  if (
    ['social', 'networking', 'dating'].includes(category)
  ) {
    addAction({
      recommendation,
      type: 'preparation_checklist',
      title: `Prepare for ${recommendation.title}`,
      description:
        'Generate an outfit, grooming, arrival and social-confidence checklist.',
      payload: {
        checklistType: 'social_event',
        include: [
          'outfit',
          'grooming',
          'arrival_time',
          'conversation_starters',
          'social_mission'
        ]
      },
      channel: 'chatgpt',
      autoExecutable: true
    });

    addAction({
      recommendation,
      type: 'feedback_request',
      title: `Collect feedback for ${recommendation.title}`,
      description:
        'Ask for attendance, rating, whether new people were met, and whether to repeat.',
      payload: {
        recommendationId: recommendation.id,
        questions: [
          'Did you attend?',
          'Rate the activity from 1 to 5.',
          'Did you meet someone new?',
          'Would you attend a similar activity again?'
        ]
      },
      channel: 'telegram',
      scheduledFor: recommendation.end || null,
      autoExecutable: true
    });
  }

  if (
    ['fitness', 'sports', 'wellness', 'recovery'].includes(category)
  ) {
    addAction({
      recommendation,
      type: 'fitness_preparation',
      title: `Prepare for ${recommendation.title}`,
      description:
        'Prepare workout, hydration, equipment and recovery guidance.',
      payload: {
        checklistType: 'fitness',
        include: [
          'equipment',
          'hydration',
          'arrival_time',
          'recovery'
        ]
      },
      channel: 'chatgpt',
      autoExecutable: true
    });

    addAction({
      recommendation,
      type: 'feedback_request',
      title: `Collect workout feedback for ${recommendation.title}`,
      description:
        'Ask for attendance, intensity, enjoyment and recovery.',
      payload: {
        recommendationId: recommendation.id,
        questions: [
          'Did you attend?',
          'Rate the session from 1 to 5.',
          'How intense was it?',
          'Would you repeat it?'
        ]
      },
      channel: 'telegram',
      scheduledFor: recommendation.end || null,
      autoExecutable: true
    });
  }

  if (category === 'travel') {
    addAction({
      recommendation,
      type: 'travel_plan',
      title: `Build travel plan for ${recommendation.title}`,
      description:
        'Prepare transport, hotel, budget, weather, packing and calendar-block options.',
      payload: {
        checklistType: 'travel',
        include: [
          'transport',
          'hotel',
          'estimated_budget',
          'weather',
          'packing',
          'calendar_block'
        ]
      },
      channel: 'chatgpt',
      autoExecutable: true
    });

    addAction({
      recommendation,
      type: 'reservation_prepare',
      title: `Prepare reservation options for ${recommendation.title}`,
      description:
        'Prepare but do not execute travel or hotel reservations.',
      payload: {
        recommendationId: recommendation.id,
        recommendation
      }
    });
  }

  addAction({
    recommendation,
    type: 'memory_update',
    title: `Store recommendation history: ${recommendation.title}`,
    description:
      'Prepare a recommendation-history record for Memory Writer.',
    payload: {
      operation: 'append_recommendation',
      record: {
        id: recommendation.id,
        title: recommendation.title,
        category: recommendation.category || 'general',
        score: recommendation.score ?? null,
        classification:
          recommendation.classification || null,
        status: 'planned',
        createdAt: new Date().toISOString()
      }
    },
    autoExecutable: true
  });
}

const summary = {
  recommendationCount: recommendations.length,
  plannedActionCount: actions.length,
  approvalRequiredCount:
    actions.filter(action => action.approvalRequired).length,
  autoExecutableCount:
    actions.filter(action => action.autoExecutable).length,
  highRiskCount:
    actions.filter(action => action.riskLevel === 'high').length,
  mediumRiskCount:
    actions.filter(action => action.riskLevel === 'medium').length,
  lowRiskCount:
    actions.filter(action => action.riskLevel === 'low').length
};

const approvalCandidates = actions
  .filter(action => action.approvalRequired)
  .map(action => ({
    type: action.type,
    status: 'proposed',
    actionId: action.actionId,
    summary: action.title,
    riskLevel: action.riskLevel,
    payload: action
  }));

const memoryUpdates = actions
  .filter(action => action.type === 'memory_update')
  .map(action => action.payload);

return [{
  json: {
    success: true,
    result: {
      summary,
      actions,
      rejectedRecommendations
    },
    memoryUpdates,
    approvalRequests: approvalCandidates,
    logs: [
      {
        timestamp: new Date().toISOString(),
        workflow: 'Concierge OS - Action Planner',
        level:
          rejectedRecommendations.length
            ? 'warning'
            : 'info',
        correlationId:
          metadata.correlationId || '',
        message:
          `Created ${actions.length} actions from ${recommendations.length} recommendations.`,
        details: {
          summary,
          rejectedCount:
            rejectedRecommendations.length
        }
      }
    ],
    nextAction: {
      type:
        approvalCandidates.length
          ? 'evaluate_approval'
          : 'format_notification',
      targetWorkflow:
        approvalCandidates.length
          ? 'Concierge OS - Approval Engine'
          : 'Concierge OS - Notification Engine'
    },
    error: null
  }
}];
